"""Write docs/content-library-v1/inventory.md from content/blog/*.md (run from the repository root)."""
from pathlib import Path
import importlib.util
import sys

ROOT = Path(__file__).resolve().parents[2]
spec = importlib.util.spec_from_file_location("content_library", ROOT / "scripts/content_library.py")
lib = importlib.util.module_from_spec(spec)
sys.modules["content_library"] = lib
spec.loader.exec_module(lib)

result = lib.build()
pub = result.published
lines = ["# Content Library V1 — inventory", "",
         "Generated by `python3 docs/content-library-v1/make_inventory.py` from the published `content/blog/*.md` sources.",
         "Every topic below is published in English, Spanish, Arabic and Brazilian Portuguese (4/4).", "",
         f"- Published topics: **{len(pub)}**; localized article pages: **{len(pub) * len(lib.LANGS)}**",
         f"- Blog listing pages per language: **{-(-len(pub) // lib.PER_PAGE)}** ({lib.PER_PAGE} per page, newest first)", ""]
lines += ["| Category | Topics |", "|---|---:|"]
for c in lib.CATEGORIES:
    lines.append(f"| {lib.L10N['en']['cat'][c]} | {sum(1 for t in pub if t.category == c)} |")
lines += ["", "## Topics (newest first)", "",
          "| # | Slug | Category | Type | Search intent | Target query | Related tools | Published | Words EN/ES/AR/PT | Sources |",
          "|---:|---|---|---|---|---|---|---|---|---|"]
for n, t in enumerate(pub, 1):
    words = "/".join(str(t.versions[l].words) for l in lib.LANGS)
    sources = "<br>".join(f"[{s['title']}]({s['url']})" for s in t.sources) or "—"
    lines.append(f"| {n} | `{t.slug}` | {lib.L10N['en']['cat'][t.category]} | {t.type} | {t.meta.get('intent', '')} | "
                 f"{t.meta.get('keyword', '')} | {', '.join(t.tools)} | {t.published.isoformat()} | {words} | {sources} |")
(ROOT / "docs/content-library-v1/inventory.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"inventory: {len(pub)} topics")
